// ─── The generated command index ──────────────────────────────────────────────
//
// ⚠️ `command-index.json` is GENERATED by `scripts/sync-command-index.mjs` from
// the CLI binary's own clap tree. Do not edit it, and do not add a list of
// commands here.
//
// This is what `EVNX_COMMANDS` tried to be. That constant was hand-written and
// omitted `spec` entirely — the same shape of error has happened five times in
// this project, and every one was found by a hand sweep, which does not repeat.

import data from "./command-index.json";

export interface IndexedSubcommand {
  /** `vault share` — the full invocation, without `evnx`. */
  path: string;
  about: string | null;
}

export interface IndexedCommand {
  name: string;
  about: string | null;
  aliases: string[];
  /**
   * Author-form path (`/guides/commands/scan`), which `DOCS_MODE` rewrites at
   * render time. ⚠️ Never the rendered `/cli/…` form — writing that produces
   * links dead on the live site.
   *
   * `null` when the command has no guide yet, which is a legitimate state: a
   * command may ship before its guide.
   */
  guide: string | null;
  /** The guide exists but is unlisted. Still reachable, still worth linking. */
  guide_draft: boolean;
  subcommands: IndexedSubcommand[];
}

export interface CommandIndex {
  schema: number;
  evnx_version: string;
  features: string[];
  commands: IndexedCommand[];
  /** Commands with no guide. ⚠️ Baked in, so a new gap shows in the diff. */
  undocumented: string[];
  /** Guides documenting a command that no longer exists. Should be empty. */
  orphan_guides: string[];
}

export const COMMAND_INDEX = data as CommandIndex;

/** The CLI version this index describes. Shown, because it will go stale. */
export const INDEXED_EVNX_VERSION = COMMAND_INDEX.evnx_version;

/** Every command and subcommand, counted the way a reader would count them. */
export function commandCount(): number {
  return COMMAND_INDEX.commands.reduce((n, c) => n + 1 + c.subcommands.length, 0);
}

// ─── Resolving a guide's `commands:` frontmatter ──────────────────────────────

/**
 * Turn an author-form guide path into the one the site serves.
 *
 * ⚠️ **One rule, one place.** `IndexedCommand.guide` is author-form
 * (`/guides/commands/scan`) because that is how guides link to each other in
 * MDX, and the rendered site serves `/cli/…`. Writing the rendered form into
 * the index would make every MDX cross-link dead; doing the rewrite inline at
 * each call site is how one of them eventually gets forgotten.
 *
 * ⚠️ The docs app renders every guide's links through this too (D-175): 352
 * `](/guides/…)` links in the MDX went out unchanged and 404ed on
 * docs.evnx.dev, which serves `/cli/…` only.
 */
export function guideHref(authorPath: string): string {
  // Root-relative `/guides` only — the index, a page, a fragment or a query on
  // either. An absolute `https://evnx.dev/guides/…` is left alone: evnx.dev
  // redirects it itself, and rewriting it would point at a path evnx.dev does
  // not serve.
  return /^\/guides(?=$|[/#?])/.test(authorPath)
    ? `/cli${authorPath.slice("/guides".length)}`
    : authorPath;
}

/** A command named by a guide's `commands:` frontmatter, resolved for display. */
export interface ResolvedCommand {
  /** The invocation without `evnx` — `"cloud pull"`. */
  path: string;
  about: string | null;
  /** Where to link, or `null` when the command has no guide yet. */
  href: string | null;
  /** The guide exists but is unlisted. Still reachable, still worth linking. */
  draft: boolean;
}

/**
 * Resolve one entry of a guide's `commands:` frontmatter against the binary's
 * own command tree.
 *
 * ⚠️ **Returns `null` for a command the binary does not have**, and callers are
 * expected to drop those rather than render them. The frontmatter is generated
 * from the page's real `evnx …` invocations and checked in CI, so today every
 * entry resolves — but a command removed in a later release would leave entries
 * behind, and a "commands covered" list that names something uninstallable is
 * worse than no list.
 *
 * ⓘ A subcommand links to its **parent's** guide, because that is where it is
 * documented: `cloud pull` lives inside `guides/commands/cloud`.
 */
export function resolveCommand(path: string): ResolvedCommand | null {
  for (const c of COMMAND_INDEX.commands) {
    if (c.name === path) {
      return {
        path,
        about: c.about,
        href: c.guide ? guideHref(c.guide) : null,
        draft: c.guide_draft,
      };
    }
    const sub = c.subcommands.find((s) => s.path === path);
    if (sub) {
      return {
        path,
        about: sub.about,
        href: c.guide ? guideHref(c.guide) : null,
        draft: c.guide_draft,
      };
    }
  }
  return null;
}

/** Resolve a whole `commands:` list, dropping anything the binary lacks. */
export function resolveCommands(paths: readonly string[] | undefined): ResolvedCommand[] {
  if (!paths?.length) return [];
  return paths
    .map(resolveCommand)
    .filter((c): c is ResolvedCommand => c !== null)
    .sort((a, b) => a.path.localeCompare(b.path));
}
